function [ucost, ttake] = takeoff(ptake, ftake, materials)
    % Convert ptake to a numeric matrix
    ptakeNumeric = cell2mat(ptake(:,1:end-1));  % Quantities
    ptakeTotal = cell2mat(ptake(:,end));        % Total costs

    % Check if there are at least 2 months for calculating unit cost
    if size(ptake, 1) < 2
        ttake = "Info is not enough";
        ucost = NaN;
        return
    end

    % Calculate unit cost for each material
    ucost = sum(ptakeNumeric) ./ sum(ptakeTotal);

    % Convert ftake to numeric matrix (quantities only)
    ftakeNumeric = cell2mat(ftake(:,1:end-1));

    % Calculate total cost for future months
    total_cost_ftake = ftakeNumeric * ucost';

    % Combine past and future quantities
    allQuantities = [ptakeNumeric; ftakeNumeric];

    % Combine past and future total costs
    total_cost_ptake = cell2mat(ptake(:,end));
    total_cost_ttake = [total_cost_ptake; total_cost_ftake];

    % Create the final ttake cell array
    % First row: materials and "cost"
    ttake = [materials', num2cell(allQuantities, 2), num2cell(total_cost_ttake, 2)];
    ttake = [ttake; "cost", "", "", "", num2cell([sum(total_cost_ptake), sum(total_cost_ftake)])];
end
